export function searchAirports(query: string, limit = 8): Airport[] {
  if (!query || query.length < 1) return []
  const q = query.toLowerCase().trim()

  const results: Array<{ airport: Airport; score: number }> = []
  const seen = new Set<string>()

  // Önce alias'larda ara
  for (const [key, alias] of Object.entries(CITY_ALIASES)) {
    if (key.startsWith(q) || key.includes(q)) {
      const score = key.startsWith(q) ? 180 : 80
      if (!seen.has(alias.iata + alias.city)) {
        results.push({ airport: alias as Airport, score })
        seen.add(alias.iata + alias.city)
      }
    }
  }

  // Sonra ana veri tabanında ara
  for (const airport of AIRPORTS) {
    const cityL = airport.city.toLowerCase()
    const countryL = airport.country.toLowerCase()
    const iataL = airport.iata.toLowerCase()
    let score = 0
    if (cityL === q) score += 200
    else if (cityL.startsWith(q)) score += 100
    else if (cityL.includes(q)) score += 60
    if (iataL === q) score += 150
    else if (iataL.startsWith(q)) score += 50
    if (countryL.includes(q)) score += 10
    if (score > 0 && !seen.has(airport.iata + airport.city)) {
      results.push({ airport, score })
      seen.add(airport.iata + airport.city)
    }
  }

  return results.sort((a, b) => b.score - a.score).slice(0, limit).map(r => r.airport)
}